import type {
  Client,
  Clawback,
  MPTokenAuthorize,
  MPTokenIssuanceCreate,
  MPTokenIssuanceSet,
  Payment,
  SubmittableTransaction,
  Wallet,
} from "xrpl";
import { convertStringToHex, fetchMPToken, fetchMPTokenIssuance, isValidAddress } from "xrpl";
import {
  DEFAULT_ASSET_SCALE,
  DEFAULT_MAXIMUM_AMOUNT,
  DEFAULT_TRANSFER_FEE,
  MPTOKEN_LSF_AUTHORIZED,
  MPTOKEN_LSF_LOCKED,
